source_new='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            v = grid[r][c]
            if v == bg:
                c += 1; continue
            a = c
            while c < w and grid[r][c] == v: c += 1
            if c-a >= 2: bars.append(('H', r, a, c-1, v))
    for c in (0, w - 1):
        r = 0
        while r < h:
            v = grid[r][c]
            if v == bg:
                r += 1; continue
            a = r
            while r < h and grid[r][c] == v: r += 1
            if r-a >= 2: bars.append(('V', c, a, r-1, v))
    if len(bars) < 2: return [row[:] for row in grid]
    # The two long runs are the opposing corner bars.
    bars = sorted(bars, key=lambda x: x[2]-x[1], reverse=True)[:2]
    barcolor = bars[0][4]
    dots = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (bg,barcolor)]
    if not dots: return [row[:] for row in grid]
    fill = Counter(grid[r][c] for r,c in dots).most_common(1)[0][0]
    dots = [(r,c) for r,c in dots if grid[r][c] == fill]
    out = [row[:] for row in grid]
    for r,c in dots: out[r][c] = 4
    def dist(bar, r, c):
        typ,pos,a,b,_=bar
        if typ=='H': return abs(pos-r) + max(a-c,0,c-b)
        return abs(pos-c) + max(a-r,0,r-b)
    near = min(bars, key=lambda bar: min(dist(bar,r,c) for r,c in dots))
    far = bars[1] if near is bars[0] else bars[0]
    typ,pos,a,b,_ = near
    ftyp,fpos,fa,fb,_ = far
    if typ=='H':
        for r,c in dots:
            if pos == h-1:
                for rr in range(r+1,h-1): out[rr][c]=fill
            else:
                for rr in range(1,r): out[rr][c]=fill
        # Copy the dot offsets onto the inward edge of the opposite bar.
        near_left = (a < w/2)
        far_left = (fa < w/2)
        for r,c in dots:
            off = (b-c) if near_left else (c-a)
            cc = (fa+off) if far_left else (fb-off)
            if fpos == 0:
                for rr in range(1,h): out[rr][cc]=fill
            else:
                for rr in range(0,h-1): out[rr][cc]=fill
    else:
        for r,c in dots:
            if pos == w-1:
                for cc in range(c+1,w-1): out[r][cc]=fill
            else:
                for cc in range(1,c): out[r][cc]=fill
        near_top = (a < h/2)
        far_top = (fa < h/2)
        for r,c in dots:
            off = (b-r) if near_top else (r-a)
            rr = (fa+off) if far_top else (fb-off)
            if fpos == 0:
                for cc in range(1,w): out[rr][cc]=fill
            else:
                for cc in range(0,w-1): out[rr][cc]=fill
    return out
'''
